<?php
wp_set_current_user(1);
$checks=array();$demos=get_posts(array('post_type'=>ppt_content_types(),'post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_ppt_demo_content','meta_value'=>'1'));
foreach($demos as $p){$issues=array();if(!$p->post_title||!trim($p->post_content))$issues[]='empty editorial content';if(stripos($p->post_content,'lorem ipsum')!==false)$issues[]='placeholder prose';if(!wp_get_object_terms($p->ID,'ppt_subject_area'))$issues[]='missing topic';foreach(get_post_meta($p->ID) as $key=>$values){if(preg_match('/_(doi|issn|isbn)$/',$key)&&!empty($values[0]))$issues[]='unexpected academic identifier';if(preg_match('/^_ppt_(journal|issue|publication_product)_id$/',$key)&&!empty($values[0])&&!get_post((int)$values[0]))$issues[]='broken relationship';}if($p->post_type==='ppt_event'&&get_post_meta($p->ID,'_ppt_event_start_date',true)<current_time('Y-m-d'))$issues[]='event not future';$checks[]=array('id'=>$p->ID,'type'=>$p->post_type,'title'=>$p->post_title,'status'=>$issues?'FAIL':'PASS','issues'=>$issues);}
file_put_contents(dirname(ABSPATH,3).'/runtime/content-results.json',wp_json_encode($checks,JSON_PRETTY_PRINT));echo count($checks).' demo records inspected; '.count(array_filter($checks,function($c){return $c['status']==='FAIL';})).' failures';
